import {strict as assert} from "node:assert";
import {parseQuota} from "./quotas.ts";
assert.equal(parseQuota("12"),12);

// Valid decimal quotas, including boundaries and surrounding whitespace.
assert.equal(parseQuota("0"), 0);
assert.equal(parseQuota("250"), 250);
assert.equal(parseQuota("  7  "), 7);
assert.equal(parseQuota("\t42\n"), 42);
assert.equal(parseQuota("   "), 0);
assert.equal(parseQuota(""), 0);

// Invalid quotas must throw rather than silently accepting or truncating them.
for (const invalid of ["-1", "1.5", "abc", "251", "250.0", "1e2", "+1"]) {
  assert.throws(() => parseQuota(invalid), /quota/i, `expected ${JSON.stringify(invalid)} to be rejected`);
}

