export const parseQuota = (value: string): number => {
  const normalized = value.trim();

  if (normalized === "") {
    return 0;
  }

  if (!/^\d+$/.test(normalized)) {
    throw new Error("Quota must be an integer between 0 and 250");
  }

  const quota = Number(normalized);

  if (!Number.isSafeInteger(quota) || quota > 250) {
    throw new Error("Quota must be an integer between 0 and 250");
  }

  return quota;
};

